import { type ParsedStop } from '../../gradient-stops/types';
/**
 * Sort gradient stops after one has been moved.
 *
 * The index of a gradient stop should depend on two things:
 * 1. The position it currently holds, and
 * 2. The direction it moved there from.
 *
 * The first piece of criteria is trivial; the second less so. What we're doing
 * to accomplish #2 here is to take the stop's index from before the move, and
 * after sorting for position values we'll sort on those "previous index" values.
 * By taking 1/10th the value of the stop's (int) index and adding it to the
 * stop's (int) position, a stop that has been moved left->right to the same
 * position as another stop will be indexed before that stop, and a stop that
 * has been moved right->left will be indexed after another stop sharing its
 * new position.
 *
 * @param {ParsedStop[]} parsedGradient Array of parsed gradient stop objects.
 *
 * @returns {ParsedStop[]} Array of GradientStop objects.
 *
 * @since 4.16.0 Added.
 *
 * @example
 * ```ts
 * // Consider the following gradient stops:
 * // [2] { position: 20 } moves to { position: 34 }
 * // [3] { position: 34 }
 * // Value for re-index comparison: [2] = 34.2, [3] = 34.3.
 * ```
 *
 * @example
 * ```ts
 * // [2] { position: 20 }
 * // [3] { position: 34 } moves to { position: 20 }
 * // Value for re-index comparison: [2] = 20.2, [3] = 20.3.
 * ```
 */
export declare const sortGradientStops: (parsedGradient: ParsedStop[]) => ParsedStop[];
